    private WebApplicationFactory<Program>? auth;private Task<HttpClient> Staff(string role)=>base.Staff(role,auth??=sql.Factory.WithWebHostBuilder(_=>{}));public Task InitializeAsync()=>sql.InitializeAsync();public async Task DisposeAsync(){auth?.Dispose();await sql.DisposeAsync();}
    private sealed record Scenario(HttpClient Customer,string Owner,string Id,string Variant,JsonNode Order,JsonNode Schedule,List<JsonNode> Cheques);
    private static string V(JsonNode n,string k)=>CreditCheckoutQuoteQa.Text(n,k);private static string Base(Scenario s)=>"/api/admin/credit/orders/"+s.Owner+"/"+s.Id;private static string Clearance(Scenario s)=>Base(s)+"/clearance";
    private static async Task<JsonNode> Read(HttpResponseMessage response)
    {
        using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: {raw}");Assert.Contains("no-store",response.Headers.CacheControl!.ToString());Assert.Contains("noindex",response.Headers.GetValues("X-Robots-Tag").Single());if(Environment.GetEnvironmentVariable("SHOP_CREDIT_CLEARANCE_WIRE_DIR")is{Length:>0}dir&&response.RequestMessage!.RequestUri!.AbsolutePath.Contains("/clearance",StringComparison.Ordinal)){Directory.CreateDirectory(dir);var id=Id();await File.WriteAllTextAsync(Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)response.StatusCode,method=response.RequestMessage.Method.Method,path=response.RequestMessage.RequestUri.PathAndQuery}));}return JsonNode.Parse(raw)!;}
    }
    private async Task<Scenario> Ready(HttpClient f,HttpClient reviewer,bool complete=true,bool zero=false,int quantity=1)
    {
        using var helper=new CreditOrderSqlTests(sql);var s=await helper.Ready(f,reviewer,quantity:quantity);if(zero){s.Customer.Dispose();await using var edit=sql.Factory.Services.CreateAsyncScope();var catalog=edit.ServiceProvider.GetRequiredService<Shop.Modules.Catalog.Infrastructure.CatalogDbContext>();var product=await catalog.Products.SingleAsync(p=>p.Variants.Any(v=>v.Id==s.Goods.Variant));product.IsDigital=true;await catalog.SaveChangesAsync();var credit=edit.ServiceProvider.GetRequiredService<CreditDbContext>();var plan=await credit.Plans.SingleAsync(p=>p.Id==s.Goods.Plan.Id);plan.DownPaymentBasisPoints=0;await credit.SaveChangesAsync();var goods=s.Goods with{Plan=s.Goods.Plan with{Version=Convert.ToBase64String(plan.Version),DownPaymentBasisPoints=0}};s=await helper.Ready(f,reviewer,goods);}var created=await CreditOrderQa.Read(await s.Customer.PostAsJsonAsync("/api/credit-orders/commands/"+Id(),new CreditOrderInput(V(s.Quote,"id"),V(s.Quote,"fingerprint"),"Synthetic financial clearance QA","09100000000",zero?null:new("IR","تهران","تهران","Synthetic only; no real goods or dispatch","1234567890"),"Synthetic QA, no person or real funds",true,true)));var order=created["order"]!;var id=V(order["summary"]!,"id");var path="/api/admin/credit/orders/"+s.Owner+"/"+id;var anchor=DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Asia/Tehran")).DateTime).ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture);var pi=new CreditSchedulePreviewInput(V(order["summary"]!,"version"),null,"Persian",anchor);var preview=await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/schedule/preview",pi));var schedule=(await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/schedule/commands/"+Id(),new SaveCreditScheduleInput(pi.OrderVersion,null,"Persian",anchor,V(preview,"fingerprint"),true))))["revision"]!;var result=new Scenario(s.Customer,s.Owner,id,s.Goods.Variant,order,schedule,[]);
        if(complete){var up=await CreditScheduleQa.Read(await f.GetAsync(path+"/upfront"));await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/upfront/commands/"+Id(),new CreditUpfrontInput(V(up,"requiredAmountRial")=="0"?"ConfirmNoUpfrontDue":"ConfirmReceipt",pi.OrderVersion,V(schedule,"version"),null,V(up,"requiredAmountRial")=="0"?"":"SYNTHETIC-UPFRONT-NOT-BANK","Synthetic private upfront note",DateTimeOffset.UtcNow,true)));foreach(var line in schedule["calculation"]!["lines"]!.AsArray()){var received=await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/cheques/receive/commands/"+Id(),new ReceiveChequeInput(pi.OrderVersion,V(schedule,"version"),line!["sequence"]!.GetValue<int>(),"SYNTHETIC-CLEARANCE-CHEQUE","Synthetic private cheque note",DateTimeOffset.UtcNow,true)));var cid=V(received["cheque"]!,"id");var approval=await CreditScheduleQa.Read(await f.PostAsJsonAsync(path+"/cheque-approvals/"+cid+"/commands/"+Id(),new ChequeApprovalInput("Approve",pi.OrderVersion,V(schedule,"version"),V(received["cheque"]!,"version"),null,"Synthetic private cheque approval",DateTimeOffset.UtcNow,true,false)));result.Cheques.Add(new JsonObject{["id"]=cid,["ledgerVersion"]=V(received["cheque"]!,"version"),["approvalVersion"]=V(approval["event"]!["summary"]!,"version")});}}return result;
    }
    private static CreditClearanceInput Input(JsonNode page,string action="Approve")=>new(action,V(page,"orderVersion"),page["current"]is{}c?V(c,"version"):null,V(page,"previewFingerprint"),"Synthetic private final finance review",true);
    private static async Task<JsonNode> Page(HttpClient f,Scenario s)=>await Read(await f.GetAsync(Clearance(s)));
    private static async Task<JsonNode> Write(HttpClient f,Scenario s,JsonNode page,string action="Approve",string? cmd=null)=>await Read(await f.PostAsJsonAsync(Clearance(s)+"/commands/"+(cmd??Id()),Input(page,action)));
    [Fact]public async Task AllFinancialConditionsCommitStockWithoutCashPaymentOrChangingOriginalReceipt()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var missing=await Ready(f,reviewer,false);using var missingCustomer=missing.Customer;var blocked=await Page(f,missing);Assert.False(blocked["canApprove"]!.GetValue<bool>());using(var fail=await f.PostAsJsonAsync(Clearance(missing)+"/commands/"+Id(),Input(blocked)))Assert.Equal(HttpStatusCode.Conflict,fail.StatusCode);
        var s=await Ready(f,reviewer);using var customer=s.Customer;var before=await CreditOrderQa.Read(await customer.GetAsync("/api/credit-orders/"+s.Id));var page=await Page(f,s);Assert.True(page["canApprove"]!.GetValue<bool>());var cmd=Id();var input=Input(page);var result=await Read(await f.PostAsJsonAsync(Clearance(s)+"/commands/"+cmd,input));Assert.True(result["initialCommit"]!.GetValue<bool>());var current=await Page(f,s);Assert.Equal("CreditApproved",V(current,"orderState"));Assert.Equal("Allocated",V(current,"reservationState"));Assert.True(current["effective"]!.GetValue<bool>());Assert.False(current["canPay"]!.GetValue<bool>());Assert.False(current["bankVerified"]!.GetValue<bool>());var own=await Read(await customer.GetAsync("/api/credit/orders/"+s.Id+"/clearance"));Assert.DoesNotContain("Synthetic private",own.ToJsonString());Assert.Null(own["evidence"]);
        var after=await CreditOrderQa.Read(await customer.GetAsync("/api/credit-orders/"+s.Id));Assert.Equal("CreditApproved",V(after["order"]!["summary"]!,"state"));Assert.Equal("credit_manual_authorization",V(after["order"]!,"paymentAvailability"));Assert.Equal(before["order"]!["summary"]!["expiresAt"]!.ToJsonString(),after["order"]!["summary"]!["expiresAt"]!.ToJsonString());Assert.Equal(before["credit"]!.ToJsonString(),after["credit"]!.ToJsonString());var replay=await Read(await f.PostAsJsonAsync(Clearance(s)+"/commands/"+cmd,input));Assert.True(replay["replayed"]!.GetValue<bool>());var recovered=await Read(await f.GetAsync(Clearance(s)+"/commands/"+cmd));Assert.Equal(result["event"]!.ToJsonString(),recovered["event"]!.ToJsonString());using(var cancel=await customer.PostAsJsonAsync("/api/orders/v2/"+s.Id+"/cancel",new{version=V(current,"orderVersion")}))Assert.Equal(HttpStatusCode.Conflict,cancel.StatusCode);
        await using var scope=sql.Factory.Services.CreateAsyncScope();var sales=scope.ServiceProvider.GetRequiredService<SalesDbContext>();Assert.Equal(0,await sales.OrderCashPayments.CountAsync());Assert.Equal(0,await sales.Orders.CountAsync(x=>x.State==OrderState.Paid));Assert.Equal(1,await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.CountAsync(x=>x.OrderId==s.Id));var stock=await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==s.Variant);Assert.Equal(1,stock.Reserved);Assert.Equal(1,await scope.ServiceProvider.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.Resource==Clearance(s)+"/commands/"+cmd));
    }
    [Fact]public async Task AuditFailureRollsBackAllocationAndCompetingApprovalHasOneCommit()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var page=await Page(f,s);var input=Input(page);var path=Clearance(s)+"/commands/"+Id();await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_ClearanceAudit CHECK ([Action]<>'CREDIT_CLEARANCE_APPROVE')");try{using var fail=await f.PostAsJsonAsync(path,input);Assert.Equal(HttpStatusCode.Conflict,fail.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_ClearanceAudit");}
        var unchanged=await Page(f,s);Assert.Equal("AwaitingPayment",V(unchanged,"orderState"));Assert.Equal("Active",V(unchanged,"reservationState"));Assert.Null(unchanged["current"]);var race=await Task.WhenAll(f.PostAsJsonAsync(path,input),f.PostAsJsonAsync(Clearance(s)+"/commands/"+Id(),input));Assert.Single(race,x=>x.IsSuccessStatusCode);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)if(r.IsSuccessStatusCode)await Read(r);else r.Dispose();await using var final=sql.Factory.Services.CreateAsyncScope();Assert.Equal(1,await final.ServiceProvider.GetRequiredService<CreditDbContext>().ClearanceEvents.CountAsync());
    }
    [Fact]public async Task LedgerChangeStopsWarehouseUntilChequeAndFinalClearanceAreReviewedAgain()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var warehouse=await Staff("Administrator");var s=await Ready(f,reviewer);using var customer=s.Customer;await Write(f,s,await Page(f,s));var page=await Page(f,s);var cheque=s.Cheques[0];var moved=await CreditScheduleQa.Read(await f.PostAsJsonAsync(Base(s)+"/cheques/"+V(cheque,"id")+"/commands/"+Id(),new MoveChequeInput(V(cheque,"ledgerVersion"),"Deposit","Synthetic custody after commitment",DateTimeOffset.UtcNow,true,true)));var stale=await Page(f,s);Assert.False(stale["effective"]!.GetValue<bool>());Assert.False(stale["canApprove"]!.GetValue<bool>());var shipment=await CreditOrderQa.Read(await warehouse.GetAsync("/api/admin/orders/"+s.Owner+"/"+s.Id+"/shipment"));Assert.False(shipment["canPack"]!.GetValue<bool>());Assert.Contains(shipment["blockers"]!.AsArray(),x=>x!.GetValue<string>()=="credit_clearance_required");
        await CreditScheduleQa.Read(await f.PostAsJsonAsync(Base(s)+"/cheque-approvals/"+V(cheque,"id")+"/commands/"+Id(),new ChequeApprovalInput("Approve",V(page,"orderVersion"),V(s.Schedule,"version"),V(moved["cheque"]!,"version"),V(cheque,"approvalVersion"),"Synthetic private renewed approval",DateTimeOffset.UtcNow,true,false)));var refreshed=await Write(f,s,await Page(f,s));Assert.False(refreshed["initialCommit"]!.GetValue<bool>());Assert.Equal(2,refreshed["event"]!["summary"]!["sequence"]!.GetValue<int>());Assert.True((await Page(f,s))["effective"]!.GetValue<bool>());var revoked=await Write(f,s,await Page(f,s),"Revoke");Assert.Equal("Revoked",V(revoked["event"]!["summary"]!,"state"));Assert.False((await Page(f,s))["effective"]!.GetValue<bool>());await Write(f,s,await Page(f,s));Assert.True((await Page(f,s))["effective"]!.GetValue<bool>());
    }
    private static async Task<AdminShipmentData> Shipment(HttpClient staff,Scenario s){var n=await CreditOrderQa.Read(await staff.GetAsync("/api/admin/orders/"+s.Owner+"/"+s.Id+"/shipment"));return JsonSerializer.Deserialize<AdminShipmentData>(n.ToJsonString(),new JsonSerializerOptions(JsonSerializerDefaults.Web))!;}
    private static ShipmentCommandInput ShipmentInput(AdminShipmentData p,string action)=>new(p.OwnerId,Id(),action,p.OrderVersion,p.Shipment?.Version,p.InventoryFingerprint,"Synthetic physical handoff QA only",true,action=="dispatch"?"حمل‌کنندهٔ ساختگی":null,action=="dispatch"?"Synthetic carrier":null,action=="dispatch"?"SYNTHETIC-001":null,action is"pack"or"repack"?null:DateTimeOffset.UtcNow);
    [Fact]public async Task WarehouseCannotDispatchRevokedAuthorizationAndDeliveryRecordsPastHandoff()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var warehouse=await Staff("Administrator");var s=await Ready(f,reviewer);using var customer=s.Customer;await Write(f,s,await Page(f,s));var packing=await Shipment(warehouse,s);Assert.True(packing.CanPack);await CreditOrderQa.Read(await warehouse.PostAsJsonAsync("/api/admin/orders/"+s.Id+"/shipment/commands",ShipmentInput(packing,"pack")));var packed=await Shipment(warehouse,s);Assert.True(packed.CanDispatch);var staleInput=ShipmentInput(packed,"dispatch");await Write(f,s,await Page(f,s),"Revoke");using(var denied=await warehouse.PostAsJsonAsync("/api/admin/orders/"+s.Id+"/shipment/commands",staleInput))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);Assert.False((await Shipment(warehouse,s)).CanDispatch);await Write(f,s,await Page(f,s));packed=await Shipment(warehouse,s);await CreditOrderQa.Read(await warehouse.PostAsJsonAsync("/api/admin/orders/"+s.Id+"/shipment/commands",ShipmentInput(packed,"dispatch")));var shipped=await Shipment(warehouse,s);Assert.True(shipped.CanDeliver);Assert.False((await Page(f,s))["canRevoke"]!.GetValue<bool>());
        var c=s.Cheques[0];await CreditScheduleQa.Read(await f.PostAsJsonAsync(Base(s)+"/cheques/"+V(c,"id")+"/commands/"+Id(),new MoveChequeInput(V(c,"ledgerVersion"),"Deposit","Synthetic after shipment custody change",DateTimeOffset.UtcNow,true,true)));Assert.False((await Page(f,s))["effective"]!.GetValue<bool>());await CreditOrderQa.Read(await warehouse.PostAsJsonAsync("/api/admin/orders/"+s.Id+"/shipment/commands",ShipmentInput(shipped,"deliver")));var final=await Page(f,s);Assert.Equal("Fulfilled",V(final,"orderState"));Assert.Equal("Fulfilled",V(final,"reservationState"));Assert.False(final["canApprove"]!.GetValue<bool>());await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Equal(0,await scope.ServiceProvider.GetRequiredService<SalesDbContext>().OrderCashPayments.CountAsync());
    }
    private sealed class FutureClock(DateTimeOffset at):TimeProvider{public override DateTimeOffset GetUtcNow()=>at;}
    private HttpClient At(HttpClient f,DateTimeOffset time,out WebApplicationFactory<Program> factory){factory=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>services.AddSingleton<TimeProvider>(new FutureClock(time))));var client=factory.CreateClient(new(){HandleCookies=false});foreach(var h in f.DefaultRequestHeaders)client.DefaultRequestHeaders.TryAddWithoutValidation(h.Key,h.Value);return client;}
    [Fact]public async Task ExpiredInitialApprovalCannotReviveHoldButCommittedReapprovalRetainsDeadline()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var page=await Page(f,s);var expires=DateTimeOffset.Parse(V(s.Order["summary"]!,"expiresAt"));using(var later=At(f,expires.AddMinutes(1),out var factory)){using(factory){using var denied=await later.PostAsJsonAsync(Clearance(s)+"/commands/"+Id(),Input(page));Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);}}
        await Write(f,s,page);using(var later=At(f,expires.AddMinutes(1),out var factory)){using(factory){var before=await Page(later,s);Assert.True(before["effective"]!.GetValue<bool>());await Write(later,s,before,"Revoke");var reapproved=await Write(later,s,await Page(later,s));Assert.False(reapproved["initialCommit"]!.GetValue<bool>());Assert.True((await Page(later,s))["effective"]!.GetValue<bool>());}}var detail=await CreditOrderQa.Read(await customer.GetAsync("/api/credit-orders/"+s.Id));Assert.Equal(V(s.Order["summary"]!,"expiresAt"),V(detail["order"]!["summary"]!,"expiresAt"));
    }
    [Fact]public async Task CancellationRaceAuthorizationAndTamperStayFailClosed()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var sales=await Staff("SalesManager");var s=await Ready(f,reviewer);using var customer=s.Customer;foreach(var denied in new[]{reviewer,sales,customer}){using var r=await denied.GetAsync(Clearance(s));Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);}var other=await Customer();using(var stranger=other.Client){using var r=await stranger.GetAsync("/api/credit/orders/"+s.Id+"/clearance");Assert.Equal(HttpStatusCode.NotFound,r.StatusCode);}using(var invalidQuery=await f.GetAsync(Clearance(s)+"/history?beforeSequence=01"))Assert.Equal(HttpStatusCode.BadRequest,invalidQuery.StatusCode);var page=await Page(f,s);var forged=JsonSerializer.SerializeToNode(Input(page),new JsonSerializerOptions(JsonSerializerDefaults.Web))!.AsObject();forged["bankVerified"]=true;using(var denied=await f.PostAsJsonAsync(Clearance(s)+"/commands/"+Id(),forged))Assert.Equal(HttpStatusCode.BadRequest,denied.StatusCode);
        var race=await Task.WhenAll(f.PostAsJsonAsync(Clearance(s)+"/commands/"+Id(),Input(page)),customer.PostAsJsonAsync("/api/orders/v2/"+s.Id+"/cancel",new{version=V(page,"orderVersion")}));Assert.Single(race,x=>x.IsSuccessStatusCode);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)r.Dispose();var fresh=await Ready(f,reviewer);using var freshCustomer=fresh.Customer;await Write(f,fresh,await Page(f,fresh));await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var e=await db.ClearanceEvents.SingleAsync(x=>x.OrderId==fresh.Id);e.State="Revoked";Assert.Equal("credit_clearance_history_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ClearanceEvents] SET [ProtectedEvent]={new byte[]{1,2,3}} WHERE [OrderId]={fresh.Id}");}using(var corrupt=await f.GetAsync(Clearance(fresh)))Assert.Equal(HttpStatusCode.ServiceUnavailable,corrupt.StatusCode);
    }

    [Fact]public async Task SqlChecksForeignKeysAndBothMigrationDownGuardsRetainFinancialHistory()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;await Write(f,s,await Page(f,s));var history=await Read(await f.GetAsync(Clearance(s)+"/history"));Assert.Single(history["items"]!.AsArray());await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.False(db.Database.HasPendingModelChanges());await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ClearanceEvents] SET [Sequence]=201 WHERE [OrderId]={s.Id}"));await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ClearanceCommands] SET [OrderId]={Id()} WHERE [OrderId]={s.Id}"));var creditError=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.GetService<IMigrator>().MigrateAsync("20261027212720_ChequeApprovals"));Assert.Equal(51000,creditError.Number);Assert.Single(await db.ClearanceEvents.ToArrayAsync());var sales=scope.ServiceProvider.GetRequiredService<SalesDbContext>();var salesError=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>sales.GetService<IMigrator>().MigrateAsync("20261027220313_ChequeReviewHold"));Assert.Equal(51000,salesError.Number);Assert.Equal(OrderState.CreditApproved,(await sales.Orders.SingleAsync(x=>x.Id==s.Id)).State);
    }

